import 'package:enough_mail/enough_mail.dart';

Future<void> main() async {
  final config = await Discover.discover('user@domain.com');
  if (config != null) {
    final account = MailAccount.fromDiscoveredSettings('account', 'user@domain.com', 'password', config);
    final mailClient = MailClient(account);
    await mailClient.connect();
    await mailClient.selectInbox();
    final messages = await mailClient.fetchMessages(count: 10);
    messages.forEach((m) => print(m.decodeSubject()));
  }
}
